(()=>{document.getElementById("year").textContent=(new Date).getFullYear();const e=window.matchMedia("(prefers-reduced-motion: reduce)"),t=document.querySelector(".form");if(t&&window.fetch){const e=t.querySelector(".form__status"),r=t.querySelector('button[type="submit"]'),n=(t,r)=>{e.textContent=t,e.className="form__status"+(r?" is-"+r:"")};t.addEventListener("submit",async e=>{e.preventDefault(),t.classList.add("is-sending"),r.disabled=!0,n("Sending…");try{const e=await fetch(t.action,{method:"POST",body:new FormData(t),headers:{Accept:"application/json"}});if(!e.ok)throw new Error(e.status);t.reset(),n("Sent. Thank you, I will reply by email.","sent")}catch(e){n("Could not send. Check your connection and try again, or message me on LinkedIn.","error")}finally{t.classList.remove("is-sending"),r.disabled=!1}})}const r=[...document.querySelectorAll(".index a")];if(!r.length||!("IntersectionObserver"in window))return;const n=new IntersectionObserver(t=>{t.forEach(t=>{var n;t.isIntersecting&&(n=t.target.id,r.forEach(t=>{const r=t.getAttribute("href")==="#"+n;if(t.classList.toggle("is-active",r),r){t.setAttribute("aria-current","true");const r=t.closest(".index");r.scrollWidth>r.clientWidth&&r.scrollTo({left:t.offsetLeft-16,behavior:e.matches?"auto":"smooth"})}else t.removeAttribute("aria-current")}))})},{rootMargin:"-30% 0px -65% 0px"});r.map(e=>document.querySelector(e.getAttribute("href"))).filter(Boolean).forEach(e=>n.observe(e))})();